                                unescapeLeadingUnderscores(name),
                                isolatedModulesLikeFlagName,
                                `${unescapeLeadingUnderscores(getSymbolOfDeclaration(location as EnumDeclaration).escapedName)}.${unescapeLeadingUnderscores(name)}`,
                            );
